steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query {
    comments(first: 100, orderBy: createdAt) {
      nodes {
        id
        body
        createdAt
        user {
          id
          name
        }
        issue {
          id
          identifier
          title
          priority
          priorityName
        }
      }
    }
  }
}'
